	path := filepath.Join(userdirs.Cache(), "install_tracked")
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return true
	}
	f, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o644)
	if err == nil {
		_ = f.Close()
		return true
	}
	if errors.Is(err, os.ErrExist) {
		return false
	}
	return true
}

